import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type PresentationMockupProps = Record<string, any>;

const PresentationMockup: React.FC<PresentationMockupProps> = ({
  backgroundColor = "#d6ebff",
  transparentBackground = false,
  durationInSeconds = 6,
  leftPhoneAccentColor = "#A0522D", // Copper/Orange edge
  rightPhoneAccentColor = "#8B0000", // Dark Red edge
  leftScreenImage = "https://images.unsplash.com/photo-1557682250-33bd709cbe85?q=80&w=1080&auto=format&fit=crop",
  centerScreenImage = "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=1080&auto=format&fit=crop",
  rightScreenImage = "https://images.unsplash.com/photo-1557682224-5b8590cd9ec5?q=80&w=1080&auto=format&fit=crop",
}) => {
  useFontLoader([]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const entranceSpringConfig = {
    damping: 18,
    stiffness: 90,
    mass: 1,
  };

  const centerEntrance = spring({
    frame,
    fps,
    config: entranceSpringConfig,
  });

  const sideEntrance = spring({
    frame: Math.max(0, frame - 4), // Slight stagger
    fps,
    config: entranceSpringConfig,
  });

  const screenOpacity = interpolate(frame, [35, 55], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Floating Math
  const centerFloat = Math.sin(frame / 25) * 12;
  const leftFloat = Math.cos(frame / 22) * 8;
  const rightFloat = Math.sin((frame + 12) / 28) * 10;

  // Device Layout Calculations
  const centerW = 460;
  const centerH = 960;
  const sideW = 380;
  const sideH = 800;

  const centerStartX = width / 2 - centerW / 2;
  const centerStartY = height / 2 - centerH / 2;
  
  const leftStartX = width / 2 - sideW / 2 - 280;
  const leftStartY = height / 2 - sideH / 2 + 60;
  
  const rightStartX = width / 2 - sideW / 2 + 280;
  const rightStartY = height / 2 - sideH / 2 + 100;

  // Interpolate entrance Y values
  const centerY = interpolate(centerEntrance, [0, 1], [1500, 0]);
  const leftY = interpolate(sideEntrance, [0, 1], [1500, 0]);
  const rightY = interpolate(sideEntrance, [0, 1], [1500, 0]);

  // Transform Strings
  const centerTransform = `translateY(${centerY + centerFloat}px) scale(1)`;
  const leftTransform = `translateY(${leftY + leftFloat}px) rotateY(-18deg) rotateZ(-5deg) scale(0.9)`;
  const rightTransform = `translateY(${rightY + rightFloat}px) rotateY(18deg) rotateZ(5deg) scale(0.9)`;

  // Reusable Phone Frame Style
  const getPhoneStyle = (
    w: number,
    h: number,
    x: number,
    y: number,
    transform: string,
    edgeColor: string,
    zIndex: number,
    edgeOffsetX: number
  ): React.CSSProperties => ({
    position: "absolute",
    left: x,
    top: y,
    width: w,
    height: h,
    backgroundColor: "#111",
    borderRadius: 45,
    border: "6px solid #222",
    transform,
    transformOrigin: "center center",
    zIndex,
    boxShadow: `inset 0px 0px 0px 2px #444, ${edgeOffsetX}px 4px 0px 0px ${edgeColor}, 20px 25px 40px rgba(0,0,0,0.4)`,
    display: "flex",
    justifyContent: "center",
    transition: "none",
  });

  // Screen Container Style
  const screenStyle: React.CSSProperties = {
    position: "absolute",
    top: 12,
    left: 12,
    right: 12,
    bottom: 12,
    backgroundColor: "#fff",
    borderRadius: 33,
    overflow: "hidden",
    transition: "none",
  };

  // Notch Style
  const notchStyle: React.CSSProperties = {
    position: "absolute",
    top: -2,
    left: "50%",
    transform: "translateX(-50%)",
    width: "45%",
    height: 30,
    backgroundColor: "#111",
    borderBottomLeftRadius: 16,
    borderBottomRightRadius: 16,
    zIndex: 10,
    transition: "none",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* 3D Scene Container */}
      <AbsoluteFill
        style={{
          perspective: 1800,
          transformStyle: "preserve-3d",
          transition: "none",
        }}
      >
        {/* Left Phone */}
        <div style={getPhoneStyle(sideW, sideH, leftStartX, leftStartY, leftTransform, leftPhoneAccentColor, 5, 8)}>
          <div style={screenStyle}>
            <div style={notchStyle} />
            <img
              src={leftScreenImage}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                opacity: screenOpacity,
                transition: "none",
                display: "block",
              }}
            />
          </div>
        </div>

        {/* Right Phone */}
        <div style={getPhoneStyle(sideW, sideH, rightStartX, rightStartY, rightTransform, rightPhoneAccentColor, 5, -8)}>
          <div style={screenStyle}>
            <div style={notchStyle} />
            <img
              src={rightScreenImage}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                opacity: screenOpacity,
                transition: "none",
                display: "block",
              }}
            />
          </div>
        </div>

        {/* Center Phone */}
        <div style={getPhoneStyle(centerW, centerH, centerStartX, centerStartY, centerTransform, "#333", 10, 0)}>
          <div style={screenStyle}>
            <div style={notchStyle} />
            <img
              src={centerScreenImage}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                opacity: screenOpacity,
                transition: "none",
                display: "block",
              }}
            />
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PresentationMockup;